def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def sum_values(values):
    total = 0
    for item in values:
        total += item
    return total

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

def unique(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result
